for n in [17,93,166,280,282]:
 c=bynum[n];name=c['name'];rules=c['rules'].replace('the controller of '+name+' sacrifices that Aura','sacrifice this Aura').replace('When you sacrifice '+name,'When you sacrifice this Aura')
 # Preserve the expressly requested granted Survival ability and its controller semantics.
 # A self-reference inside the creature's granted ability cannot safely call the source Aura "this Aura".
 rules=c['rules'].replace('When you sacrifice '+name,'When you sacrifice this Aura')
 change(n,'Use this Aura in the Aura\'s own reward ability; retain the necessary named source inside the granted creature ability.','Does the shorter reward remain readable while the granted Survival ability preserves its original multiplayer behaviour?',rules=rules)
change(7,'Make the foot-washing recognition scene a second common direct-return enabler; blink also reveals a manifested permanent.','Does two mana and tapped return sufficiently constrain repeated ETB value? Compare lost untap combat utility.',['Cloudshift','Ephemerate'],mana='{1}{W}',rules="Exile target creature you control, then return that card to the battlefield tapped under its owner's control. You gain 2 life.",mechanics='Blink; recognition; life',flavorStoryElement='Eurycleia washes the disguised Odysseus and recognises his scar. The familiar person becomes visible through care.',flavorMatchScore=4,flavorMatchRationale='Blink removes the face-down presentation of a manifested permanent and renews entry effects; tapped return conveys rest. Disappearance is a gameplay abstraction, not a literal feature of the scene. A manifested instant or sorcery cannot return to the battlefield.',storySourceBand='Odyssey Book XIX / Eurycleia recognises the scar')
change(51,'Connect counsel and identity to the supported face-up action while limiting repeated untap engines.','Can players order recognition and Survival triggers correctly, and does one untap per turn offer enough reward?',rules='Whenever one or more cards are exiled from your library for the first time each turn, tap up to one target creature an opponent controls.\nWhenever a permanent you control enters from exile or is turned face up, untap up to one target creature you control. This ability triggers only once each turn.',mechanics='Library exile; face-up recognition; limited untap',flavorStoryElement='Mentor defends the household; Athena takes his form and helps Telemachus prepare and depart.',flavorMatchScore=4,flavorMatchRationale='Concealment opens a way through opposition; recognition readies an ally. The tap/untap model abstracts coordinated assistance, not a literal restoration of the dead. Distinguish human Mentor from Athena in his likeness.')
change(90,'Make Nausicaa welcome both the returning traveller and the newly revealed person. Preserve her Adventure.','Does the two-mana body plus counter reward compete fairly with the other signposts? The Adventure alone still does not trigger this ability.',rules="Whenever a permanent you control enters from exile or is turned face up, untap it. If it's a creature, put a +1/+1 counter on it. This ability triggers only once each turn.\n//Adventure// Find the Castaway — {1}{U} — Sorcery — Adventure\nManifest fate.",mechanics='Adventure; Manifest Fate; face-up recognition; counters',flavorStoryElement='Nausicaa stands her ground, supplies the castaway, and sees his transformed appearance after washing and clothing.',flavorMatchScore=4,flavorMatchRationale='Her Adventure discovers the unknown traveller; later revelation or return lets her restore and strengthen them. The new event explicitly supports face-up play. Generic exile still stands for welcome rather than a literal journey from another realm.')
change(56,'Replace benevolent rescue with consumption of household resources for personal growth and pressure.','Is a 3/3 that can grow once at each of your end steps too efficient with recurring Food? Check death triggers, copied triggers and extra end steps.',['Ravenous Squirrel'],rules='At the beginning of your end step, you may sacrifice another creature or a Food. If you do, put a +1/+1 counter on Antinous and each opponent loses 1 life.',mechanics='End-step sacrifice; Food; growth; opponent life loss',flavorStoryElement='Antinous consumes the absent king’s household resources, pressures the heir and refuses generosity to the disguised stranger.',flavorMatchScore=4,flavorMatchRationale='The player gives up household bodies or provisions; Antinous alone grows while rivals lose life. Sacrificing your own resources is an abstraction of his control within the occupied household, not literal theft from the opposing player. The card supplies no rescue or replacement body.')
change(213,'Replace repeated disappearance with a bond to the household ground and a reward for reunion.','Is three mana too efficient for a protected draw engine in legend-dense Commander decks? Test chosen-land tracking, removal windows and the two-creature threshold.',['Flowering of the White Tree','Tome of Legends'],rules='As this artifact enters, choose a land you control.\nAs long as you control the chosen land, this artifact has hexproof and legendary creatures you control have ward {1}.\nAt the beginning of your end step, if you control the chosen land and two or more legendary creatures, draw a card.',mechanics='Chosen land; hexproof; legendary ward; reunion draw',storySourceBand='Odyssey Book XXIII / the rooted bed and recognition test',flavorStoryElement='Odysseus built the marriage bed around an olive trunk. Penelope tests his identity by ordering it moved; his knowledge of its construction proves their shared history.',flavorMatchScore=4,flavorMatchRationale='A particular land anchors the protection and reunion reward; losing that land disables them. Two legendary creatures stand for the reunited couple. Hexproof and card draw are gameplay abstractions; the design does not prohibit all movement or require the specific spouses.')
change(235,'Give the opened bag an actual cost in enduring progress, and depict its contents as wind rather than real treasure.','Does the delayed land loss make this unattractive without counter manipulation, or too efficient when chapter III is avoided? Test Penelope and other ways to repeat chapter II.',['Reckless Impulse','Seething Song'],rules='I — Exile the top two cards of your library. Until the end of your next turn, you may play those cards.\nII — Add {R}{R}{R}.\nIII — Sacrifice a land.',mechanics='Saga; impulse access; ritual mana; land sacrifice',storySourceBand='Odyssey Book X / Aeolus and the opened bag',flavorStoryElement='Within sight of home, the crew mistakes Aeolus’s bag of winds for hidden wealth. Opening it releases a storm that drives the ships back to Aeolus, who refuses further help.',flavorMatchScore=4,flavorMatchRationale='Temporary access tempts the player, a mana burst represents released force, and land sacrifice removes durable progress. These are game abstractions: the crew finds no actual treasure and no literal island is destroyed. Counter manipulation can postpone the price, so catastrophe is not guaranteed by this text.')
def metrics(cs):
 common=[c for c in cs if c['rarity']=='C'];nonland=[c for c in common if 'Land' not in c['type']]
 return {'cards':len(cs),'rarity':dict(collections.Counter(c['rarity'] for c in cs)),'lands':sum('Land' in c['type'] for c in cs),'doubleFaced':sum(c['layout']=='transform' for c in cs),'commonCreatures':sum('Creature' in c['type'] for c in nonland),'commonEnchantmentCreatures':sum('Enchantment Creature' in c['type'] for c in nonland),'commonEnchantments':sum('Enchantment' in c['type'] for c in nonland),'commonFoodSources':sum('create a food token' in c['rules'].lower() or 'Artifact — Food' in c['type'] for c in nonland),'commonManifestFate':sum('manifest fate' in c['rules'].lower() for c in nonland),'commonForetell':sum('foretell' in c['rules'].lower() for c in nonland),'commonEscape':sum('escape' in c['rules'].lower() for c in nonland),'commonGift':sum('Gift a Food' in c['rules'] for c in nonland),'commonConstellation':sum('Constellation' in c['rules'] for c in nonland),'commonCreatureByColor':dict(collections.Counter(c['color'] for c in nonland if 'Creature' in c['type']))}
summary={'status':'isolated-playtest-candidate-not-live','baseDatasetVersion':base['datasetVersion'],'changedCards':len(changes),'before':metrics(base['cards']),'after':metrics(cards),'warnings':['No played matches have been performed.','Source briefs are a first pass; unresolved passage verification remains labelled.','Hunter approved WU Penelope and explicitly selected actual sacrifice for Iphigenia. Slot 015 now remains UB; its proposed rate still needs testing.','The Ordeals still grant Survival to their enchanted creatures; source names remain where self-reference would change meaning.','The seven Studio notes remain open until actual implementation is verified.','Candidate references need a production refresh before integration.']}
assert len(cards)==309 and len({c['id'] for c in cards})==309
assert summary['before']['rarity']==summary['after']['rarity'] and summary['after']['lands']==40 and summary['after']['doubleFaced']==1
protected=['id','number','rarity','primaryArt','credit','source','imageUrl','productLayer']
for old,new in zip(base['cards'],cards):
 for k in protected: assert old.get(k)==new.get(k),(old['id'],k)
for name,value in [('candidate-cards.json',{'schema':'odyssey-design-candidate/v1','summary':summary,'cards':cards}),('candidate-changes.json',changes),('candidate-summary.json',summary)]:
 (OUT/name).write_text(json.dumps(value,ensure_ascii=False,indent=2)+'\n')
print(json.dumps(summary,indent=2))
